#include "Monstey_FearDbNames.hpp"
#include "Monstey_Json.hpp"
#include <array>
#include <bit>
#include <fstream>
#include <iostream>
#include <vector>
using namespace Monstey;
namespace {
using Monstey_U32=std::uint32_t;std::uint64_t Monstey_Groups=0,Monstey_Cases=0,Monstey_Checks=0;
void Monstey_Check(bool value,const char* text){++Monstey_Checks;if(!value)throw std::runtime_error(text);}
struct Monstey_Arena {Monstey_U32 base=0x1000;std::vector<std::uint8_t> bytes=std::vector<std::uint8_t>(0x2000);Monstey_FearDbMemory Memory()const{return {base,bytes};}void Put(Monstey_U32 at,Monstey_U32 value,unsigned width=4){for(unsigned i=0;i<width;++i)bytes.at(at-base+i)=static_cast<std::uint8_t>(value>>(i*8));}void Node(Monstey_U32 parent,Monstey_U32 count,Monstey_U32 table){Put(parent+8,count);Put(parent+12,table);}void Query(Monstey_U32 at=0x1100){Put(at,'q',1);}};
using Monstey_Transcript=std::vector<std::array<Monstey_U32,2>>;
Monstey_U32 Monstey_Reference(const std::vector<Monstey_U32>&names,Monstey_U32 query,Monstey_Transcript&calls,int low,int high){if(low>high)return 0;const auto mid=(low+high)/2;const auto candidate=names[static_cast<std::size_t>(mid)];if(query==0){if(candidate==0)return 0x1800u+static_cast<Monstey_U32>(mid)*16u;return Monstey_Reference(names,query,calls,low,mid-1);}if(candidate==0)return Monstey_Reference(names,query,calls,mid+1,high);calls.push_back({query,candidate});if(query==candidate)return 0x1800u+static_cast<Monstey_U32>(mid)*16u;return query<candidate?Monstey_Reference(names,query,calls,low,mid-1):Monstey_Reference(names,query,calls,mid+1,high);}
void Monstey_Enumerate(){for(unsigned length=0;length<=8;++length){unsigned total=1;for(unsigned i=0;i<length;++i)total*=3;for(unsigned code=0;code<total;++code){Monstey_Arena a;std::vector<Monstey_U32> names;unsigned left=code;for(unsigned i=0;i<length;++i){const auto v=left%3u;left/=3;names.push_back(v);a.Put(0x1800+i*16,v);}for(Monstey_U32 query=0;query<=3;++query){Monstey_Transcript actual,expected;const Monstey_FearDbNameCompare compare=[&](auto q,auto candidate){actual.push_back({q,candidate});return q<candidate?-256:q>candidate?256:0;};const auto expected_row=Monstey_Reference(names,query,expected,0,static_cast<int>(length)-1);const auto result=Monstey_FearDbBinaryNameSearch(a.Memory(),0x1800,length,query,compare);Monstey_Check(result==expected_row,"recursive ordered branch reference");Monstey_Check(actual==expected,"exact comparator identity/order/null transcript");++Monstey_Cases;}}}++Monstey_Groups;}
void Monstey_SignedResults(){for(auto value:std::array<std::int32_t,9>{0,1,256,65536,INT32_MAX,-1,-256,-65536,INT32_MIN}){Monstey_Arena a;for(unsigned i=0;i<3;++i)a.Put(0x1800+i*16,0x1200+i);Monstey_Transcript actual;const Monstey_FearDbNameCompare compare=[&](auto q,auto candidate){actual.push_back({q,candidate});return actual.size()==1?value:0;};const auto result=Monstey_FearDbBinaryNameSearch(a.Memory(),0x1800,3,0x7777,compare);Monstey_Check(result==(value==0?0x1810u:value<0?0x1800u:0x1820u),"signed full EAX result, no low-byte equality");Monstey_Check(actual.size()==(value==0?1u:2u),"signed comparator call count");++Monstey_Cases;}++Monstey_Groups;}
void Monstey_WideCounts(){for(auto count:std::array<Monstey_U32,8>{0,1,2,7,0x7fffffffu,0x80000000u,0x80000001u,0xffffffffu}){Monstey_Arena a;const auto high=count-1u;const bool skipped=(high&0x80000000u)!=0;const auto middle=high/2u;const auto table=0x1800u-middle*16u;a.Put(0x1800,0x9999);unsigned calls=0;const Monstey_FearDbNameCompare compare=[&](auto,auto){++calls;return 0;};const auto result=Monstey_FearDbBinaryNameSearch(a.Memory(),table,count,0x7777,compare);Monstey_Check(result==(skipped?0u:0x1800u)&&calls==(skipped?0u:1u),"native signed high gate and wrapped row address");++Monstey_Cases;}
 Monstey_Arena a;a.Put(0x17f0,0x1111);a.Put(0x1800,0x2222);std::vector<Monstey_U32> calls;const Monstey_FearDbNameCompare compare=[&](auto,auto candidate){calls.push_back(candidate);return calls.size()==1?1:0;};const auto result=Monstey_FearDbBinaryNameSearch(a.Memory(),0x1800,0x80000000u,1,compare);Monstey_Check(result==0x1800&&calls==std::vector<Monstey_U32>{0x1111,0x2222},"signed sum overflow uses CDQ SUB SAR not unsigned midpoint");++Monstey_Cases;
 calls.clear();
 const Monstey_FearDbNameCompare stop_compare=[&](auto,auto candidate){calls.push_back(candidate);return calls.size()==1?1:calls.size()==2?-1:0;};
 const auto stopped=Monstey_FearDbBinaryNameSearch(a.Memory(),0x1800,0x80000000u,1,stop_compare);
 Monstey_Check(stopped==0&&calls==std::vector<Monstey_U32>{0x1111,0x2222},"signed negative high after second comparison stops, no unsigned-mid continuation");
 ++Monstey_Cases;++Monstey_Groups;}
void Monstey_Guards(){Monstey_Arena a;a.Query();a.Put(0x1101,0,1);a.Node(0x1200,1,0x1800);a.Put(0x1800,0x1111);unsigned calls=0;const Monstey_FearDbNameCompare compare=[&](auto,auto){++calls;return 0;};for(auto h:std::array<Monstey_U32,2>{0,0x1200})for(auto q:std::array<Monstey_U32,3>{0,0x1100,0x1101}){const auto result=Monstey_FearDbGuardedChildName(a.Memory(),h,q,compare);Monstey_Check(result==(h!=0&&q==0x1100?0x1800u:0u),"parent/query/firstbyte gates");++Monstey_Cases;}Monstey_Check(calls==1,"guarded filtered branches do not invoke CRT");a.Put(0x1800,0);Monstey_Check(Monstey_FearDbRawChildrenName(a.Memory(),0x1200,0,{})==0x1800,"raw null query equals null candidate without comparator");Monstey_Check(Monstey_FearDbRawChildrenName(a.Memory(),0x1200,0x1100,{})==0,"nonnull query skips null row without comparator");Monstey_Check(Monstey_FearDbBinaryNameSearch(a.Memory(),0x1800,1,0x1101,compare)==0,"raw empty query does not override null-row skip");++Monstey_Cases;++Monstey_Groups;}
void Monstey_Wrappers(){Monstey_Arena a;a.Query(0x1100);a.Query(0x1102);a.Put(0x1101,0,1);a.Node(0x1200,1,0x1800);a.Put(0x1800,0x1100);a.Node(0x1800,1,0x1900);a.Put(0x1900,0);a.Node(0x1900,1,0x1a00);a.Put(0x1a00,0);Monstey_Transcript calls;const Monstey_FearDbNameCompare compare=[&](auto q,auto candidate){calls.push_back({q,candidate});return 0;};Monstey_Check(Monstey_FearDbRecordByNames(a.Memory(),0x1200,0x1100,0,compare)==0x1900,"database record wrapper final null bypasses guard");Monstey_Check(calls==Monstey_Transcript{{0x1100,0x1100}},"null final record never calls comparator");Monstey_Check(Monstey_FearDbGuardedChildName(a.Memory(),0x1800,0,compare)==0,"direct record null differs from wrapper");Monstey_Check(Monstey_FearDbAttributeInDatabaseByNames(a.Memory(),0x1200,0x1100,0,0,compare)==0x1a00,"database attribute final raw null branches");Monstey_Check(Monstey_FearDbAttributeByNames(a.Memory(),0x1800,0,0x1102,{})==0,"category attribute guarded record null skips final");
 a.Put(0x1900,0x1101);a.Put(0x1a00,0x1101);calls.clear();Monstey_Check(Monstey_FearDbRecordByNames(a.Memory(),0x1200,0x1100,0x1101,compare)==0x1900,"database record empty final name is compared");Monstey_Check(calls==Monstey_Transcript{{0x1100,0x1100},{0x1101,0x1101}},"empty final query identity delivered unchanged");Monstey_Check(Monstey_FearDbGuardedChildName(a.Memory(),0x1800,0x1101,compare)==0,"direct empty record rejects");a.Put(0x1900,0x1102);calls.clear();Monstey_Check(Monstey_FearDbAttributeByNames(a.Memory(),0x1800,0x1102,0x1101,compare)==0x1a00,"category attribute final empty name compared");Monstey_Check(calls==Monstey_Transcript{{0x1102,0x1102},{0x1101,0x1101}},"attribute comparison order");Monstey_Cases+=9;++Monstey_Groups;}
void Monstey_LiveReads(){Monstey_Arena a;a.Query();a.Node(0x1200,5,0x1800);for(unsigned i=0;i<5;++i)a.Put(0x1800+i*16,0x2100+i);std::vector<Monstey_U32> calls;const Monstey_FearDbNameCompare compare=[&](auto,auto candidate){calls.push_back(candidate);if(calls.size()==1){a.Put(0x1800,0x2222);a.Node(0x1200,1,0x1b00);a.Put(0x1b00,0x3333);return -1;}return 0;};const auto result=Monstey_FearDbRawChildrenName(a.Memory(),0x1200,0x1100,compare);Monstey_Check(result==0x1800&&calls==std::vector<Monstey_U32>{0x2102,0x2222},"rows live; table/count captured only once");calls.clear();const auto next=Monstey_FearDbRawChildrenName(a.Memory(),0x1200,0x1100,[&](auto,auto candidate){calls.push_back(candidate);return 0;});Monstey_Check(next==0x1b00&&calls==std::vector<Monstey_U32>{0x3333},"next lookup reloads changed parent metadata");Monstey_Cases+=2;++Monstey_Groups;}
template<class Monstey_Call>void Monstey_Fault(Monstey_Call&&call,Monstey_U32 at,unsigned width){bool caught=false;try{call();}catch(const Monstey_FearDbFault&e){caught=e.address==at&&e.width==width&&!e.writing;}Monstey_Check(caught,"first consumed native read boundary");++Monstey_Cases;}
void Monstey_FaultOrder(){Monstey_Arena a;a.Query();a.Node(0x1200,0,0x1800);const Monstey_FearDbMemory empty{0,{}};Monstey_Check(Monstey_FearDbGuardedChildName(empty,0,0xffffffff,{})==0,"null parent skips invalid query");Monstey_Check(Monstey_FearDbGuardedChildName(empty,0x1200,0,{})==0,"null query skips firstbyte and parent");Monstey_Fault([&]{(void)Monstey_FearDbGuardedChildName(empty,0x1200,0x1100,{});},0x1100,1);Monstey_Fault([&]{(void)Monstey_FearDbRawChildrenName(empty,0x1200,0,{});},0x120c,4);const Monstey_FearDbMemory only_count{0x1208,std::span<const std::uint8_t>(a.bytes).subspan(0x208,4)};Monstey_Fault([&]{(void)Monstey_FearDbRawChildrenName(only_count,0x1200,0,{});},0x120c,4);const Monstey_FearDbMemory only_pointer{0x120c,std::span<const std::uint8_t>(a.bytes).subspan(0x20c,4)};Monstey_Fault([&]{(void)Monstey_FearDbRawChildrenName(only_pointer,0x1200,0,{});},0x1208,4);Monstey_Fault([&]{(void)Monstey_FearDbBinaryNameSearch(empty,0x1800,1,0,{});},0x1800,4);Monstey_Check(Monstey_FearDbBinaryNameSearch(empty,0xffffffff,0,1,{})==0,"empty raw search does not consume table or comparator");Monstey_Cases+=3;++Monstey_Groups;}
void Monstey_ExternalBoundary(){Monstey_Arena a;a.Put(0x1800,0x2100);bool missing=false;try{(void)Monstey_FearDbBinaryNameSearch(a.Memory(),0x1800,1,0x1100,{});}catch(const std::invalid_argument&){missing=true;}Monstey_Check(missing,"nonnull comparison requires external callable");bool propagated=false;try{(void)Monstey_FearDbBinaryNameSearch(a.Memory(),0x1800,1,0x1100,[&](auto,auto)->std::int32_t{a.Put(0x1800,0x9999);throw std::runtime_error("sentinel external failure");});}catch(const std::runtime_error&e){propagated=std::string(e.what())=="sentinel external failure";}Monstey_Check(propagated,"external exception propagates without fallback");std::vector<Monstey_U32> seen;const auto result=Monstey_FearDbBinaryNameSearch(a.Memory(),0x1800,1,0x1100,[&](auto,auto c){seen.push_back(c);return 0;});Monstey_Check(result==0x1800&&seen==std::vector<Monstey_U32>{0x9999},"external side effects retained");Monstey_Cases+=3;++Monstey_Groups;}
}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("NEW report required");Monstey_Enumerate();Monstey_SignedResults();Monstey_WideCounts();Monstey_Guards();Monstey_Wrappers();Monstey_LiveReads();Monstey_FaultOrder();Monstey_ExternalBoundary();std::ofstream(argv[1],std::ios::binary)<<Monstey_Json::object({{"schema","Monstey.FearDbNameTests/1"},{"passed",true},{"groups",Monstey_Groups},{"cases",Monstey_Cases},{"checks",Monstey_Checks},{"synthetic_only",true},{"historical_comparator_policy_claimed",false},{"original_executed",false}}).dump(2)<<'\n';std::cout<<"PASS "<<Monstey_Groups<<" groups "<<Monstey_Cases<<" cases "<<Monstey_Checks<<" checks\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
